<script setup>
import { ref, computed } from 'vue';
import { Head, Link, useForm, usePage, router } from '@inertiajs/vue3';
import { ArrowLeft, ArrowRight, Check, X, ShieldCheck, LogOut } from 'lucide-vue-next';
const props=defineProps({data:Object,isAdmin:Boolean,isModerator:Boolean,isCurator:Boolean,ownPlaces:Array,queue:Array,reviews:Array,reports:Array,requests:Array});
const page=usePage(), section=ref('Мои места'), editing=ref(null);
const form=useForm({name:'',description:'',address:'',vertical_id:props.data.verticals[0]?.id,category_id:props.data.categories[0]?.id,lat:48.015,lng:37.805,phone:'',price_level:1,visit_format:'individual',details:{},photos:[],rights_confirmed:false});
const vertical=useForm({name:'',slug:'',description:'',color:'#547864',fields:[]});
const fields=ref('');
const investment=useForm({investment_site_id:Number(new URLSearchParams(location.search).get('site'))||props.data.sites[0]?.id,project:'',description:'',contact:page.props.auth.user.email});
const journey=useForm({name:'',description:'',duration:120,stops:[],published:true});
const activeVertical=computed(()=>props.data.verticals.find(v=>v.id===Number(form.vertical_id)));
const tabs=computed(()=>['Мои места','Инвестору',...(props.isModerator?['Модерация','Маршруты']:[]),...(props.isAdmin?['Вертикали']:[]),...(props.isCurator?['Заявки инвесторов']:[])]);
const statuses={new:'Новая',in_progress:'В работе',approved:'Одобрена',rejected:'Отклонена',draft:'Черновик',on_moderation:'На модерации'};
function submitPlace() {if(editing.value) form.post('/platform/places/'+editing.value,{onSuccess:()=>{form.reset();editing.value=null;}});else form.post('/platform/places',{onSuccess:()=>form.reset()});}
function edit(p) {editing.value=p.id;Object.assign(form,{name:p.name,description:p.description,address:p.address,vertical_id:p.vertical_id,category_id:p.category_id,lat:p.lat,lng:p.lng,phone:p.phone,price_level:p.price_level,visit_format:p.visit_format,details:{...(p.details??{})},rights_confirmed:false});window.scrollTo({top:0,behavior:'smooth'});}
function addVertical() {vertical.fields=fields.value.split(',').map(s=>s.trim()).filter(Boolean);vertical.post('/platform/verticals',{onSuccess:()=>{vertical.reset();fields.value='';}});}
function updateRequest(e,id) {const fd=new FormData(e.target);router.put('/platform/investments/'+id,{status:fd.get('status'),response:fd.get('response')},{preserveScroll:true});}
if(new URLSearchParams(location.search).has('site')) section.value='Инвестору';
</script>
<template>
<Head title="Личный кабинет"/>
<main class="workspace">
<header><Link href="/" class="brand"><span class="brand-symbol">к<span>·</span></span><span>КОД<br><b>НОВОРОССИИ</b></span></Link><Link class="text-link" href="/"><ArrowLeft :size="16"/> К путеводителю</Link><button class="text-link" @click="router.post('/logout')"><LogOut :size="16"/>Выйти</button></header>
<p class="eyebrow">ВАШЕ МЕСТО В РЕГИОНЕ</p><h1>Здравствуйте, {{page.props.auth.user.name}}</h1><p class="lead">Управляйте объектами, следите за заявками и развивайте регион.</p>
<p v-if="page.props.flash?.success" class="flash" role="status">{{page.props.flash.success}}</p><p v-if="Object.keys(page.props.errors??{}).length" class="form-error">{{Object.values(page.props.errors).flat().join(' ')}}</p>
<div class="workspace-tabs"><button v-for="t in tabs" :key="t" :class="{active:section===t}" @click="section=t">{{t}}</button></div>
<section v-if="section==='Мои места'">
<div class="workspace-section"><h2>{{editing?'Редактирование карточки':'Добавьте своё место'}}</h2><p class="muted">После проверки модератором объект появится в каталоге и на карте.</p><form class="workspace-form" @submit.prevent="submitPlace">
<label>Название<input v-model="form.name" required maxlength="180"></label><label>Вертикаль<select v-model="form.vertical_id" @change="form.details={}"><option v-for="v in data.verticals" :key="v.id" :value="v.id">{{v.name}}</option></select></label><label>Категория<select v-model="form.category_id"><option v-for="c in data.categories" :key="c.id" :value="c.id">{{c.name}}</option></select></label><label>Адрес<input v-model="form.address" required maxlength="255"></label><label class="wide">Описание<textarea v-model="form.description" required maxlength="6000"></textarea></label><label>Широта<input v-model="form.lat" type="number" step="any" min="-90" max="90" required></label><label>Долгота<input v-model="form.lng" type="number" step="any" min="-180" max="180" required></label><label>Телефон<input v-model="form.phone" maxlength="20"></label><label>Стоимость<select v-model="form.price_level"><option :value="1">Бесплатно / бюджетно</option><option :value="2">₽₽</option><option :value="3">₽₽₽</option><option :value="4">₽₽₽₽</option></select></label><label>Посещение<select v-model="form.visit_format"><option value="individual">Самостоятельно</option><option value="group">С группой</option><option value="booking">По записи</option></select></label><label v-for="field in activeVertical?.fields??[]" :key="field">{{field}}<input v-model="form.details[field]" maxlength="500"></label><label class="wide">Фото (до 5 файлов, JPG / PNG / WebP, до 4 МБ)<input type="file" accept="image/jpeg,image/png,image/webp" multiple @change="form.photos=Array.from($event.target.files).slice(0,5)"></label><label class="wide check-label"><input v-model="form.rights_confirmed" type="checkbox" required>Подтверждаю права на публикуемый текст и материалы.</label><div class="wide button-row"><button class="primary" :disabled="form.processing">Отправить на модерацию <ArrowRight :size="16"/></button><button v-if="editing" type="button" class="secondary" @click="editing=null;form.reset()">Отмена</button></div>
</form></div><div class="workspace-section"><h2>Мои объекты</h2><article v-for="p in ownPlaces" :key="p.id" class="queue-row"><h3>{{p.name}}</h3><p>{{p.address}}</p><span class="badge-status">{{statuses[p.status]??p.status}}</span><button class="text-link" @click="edit(p)">Редактировать</button><Link v-if="p.status==='approved'" :href="'/explore/'+p.slug" class="text-link ml-4">Открыть карточку</Link></article><p v-if="!ownPlaces.length" class="muted">У вас пока нет объектов.</p></div>
</section>
<section v-if="section==='Инвестору'" class="workspace-section"><h2>Заявка куратору</h2><form class="workspace-form" @submit.prevent="investment.post('/platform/investments',{onSuccess:()=>investment.reset('project','description')})"><label>Площадка<select v-model="investment.investment_site_id"><option v-for="s in data.sites" :value="s.id" :key="s.id">{{s.name}}</option></select></label><label>Название проекта<input v-model="investment.project" required maxlength="180"></label><label class="wide">Идея и условия<textarea v-model="investment.description" required maxlength="4000"></textarea></label><label>Как с вами связаться<input v-model="investment.contact" required maxlength="180"></label><div class="wide"><button class="primary" :disabled="investment.processing">Отправить заявку</button></div></form><hr><h2>Мои заявки</h2><article v-for="r in requests.filter(r=>r.user_id===page.props.auth.user.id)" :key="r.id" class="queue-row"><span class="badge-status">{{statuses[r.status]}}</span><h3 class="mt-3">{{r.project}}</h3><p>{{r.description}}</p><p v-if="r.response"><b>Ответ куратора:</b> {{r.response}}</p></article><p v-if="!requests.some(r=>r.user_id===page.props.auth.user.id)" class="muted">Здесь появятся обращения и ответы куратора.</p></section>
<section v-if="section==='Вертикали'" class="workspace-section"><h2>Новая вертикаль</h2><p class="muted">Новые вертикали и дополнительные поля доступны без пересборки приложения.</p><form class="workspace-form" @submit.prevent="addVertical"><label>Название<input v-model="vertical.name" required maxlength="100"></label><label>Код латиницей<input v-model="vertical.slug" required pattern="[a-zA-Z0-9_-]+" placeholder="industrial-tourism"></label><label>Цвет<input v-model="vertical.color" type="color"></label><label>Поля через запятую<input v-model="fields" placeholder="Услуги, Портфолио, Стажировки"></label><label class="wide">Описание<textarea v-model="vertical.description" maxlength="500"></textarea></label><div><button class="primary" :disabled="vertical.processing">Создать вертикаль</button></div></form><hr><article v-for="v in data.verticals" :key="v.id" class="queue-row"><h3 :style="{color:v.color}">{{v.name}}</h3><p>{{v.description}}</p><p>Поля: {{v.fields?.join(', ')||'Нет дополнительных полей'}}</p></article></section>
<section v-if="section==='Модерация'">
<div class="workspace-section"><h2>Объекты на проверке · {{queue.length}}</h2><article v-for="p in queue" :key="p.id" class="queue-row"><h3>{{p.name}}</h3><p>{{p.description}}</p><p>{{p.address}} · {{p.lat}}, {{p.lng}}</p><div class="button-row"><button class="primary" @click="router.post('/platform/places/'+p.id+'/moderate',{approved:true},{preserveScroll:true})">Опубликовать</button><button class="secondary" @click="router.post('/platform/places/'+p.id+'/moderate',{approved:false},{preserveScroll:true})">Отклонить</button></div></article><p v-if="!queue.length" class="muted">Все карточки проверены.</p></div>
<div class="workspace-section"><h2>Отзывы · {{reviews.length}}</h2><article v-for="r in reviews" :key="r.id" class="queue-row"><h3>{{r.place?.name}} · {{r.rating}}/5</h3><p>{{r.author_name}}: {{r.text}}</p><div class="button-row"><button class="primary" @click="router.post('/platform/reviews/'+r.id+'/moderate',{approved:true},{preserveScroll:true})">Опубликовать</button><button class="secondary" @click="router.post('/platform/reviews/'+r.id+'/moderate',{approved:false},{preserveScroll:true})">Отклонить</button></div></article><p v-if="!reviews.length" class="muted">Новых отзывов нет.</p></div>
<div class="workspace-section"><h2>Сообщения · {{reports.length}}</h2><article v-for="r in reports" :key="r.id" class="queue-row"><span class="badge-status">{{{inaccuracy:'Неточность',copyright:'Авторские права',review:'Жалоба на отзыв'}[r.type]}}</span><p class="mt-3">Объект №{{r.place_id}}: {{r.message}}</p><button class="secondary" @click="router.post('/platform/reports/'+r.id+'/resolve',{},{preserveScroll:true})">Отметить решённым</button></article><p v-if="!reports.length" class="muted">Новых обращений нет.</p></div>
</section>
<section v-if="section==='Маршруты'" class="workspace-section"><h2>Опубликовать маршрут</h2><form class="workspace-form" @submit.prevent="journey.post('/platform/journeys',{onSuccess:()=>journey.reset()})"><label>Название<input v-model="journey.name" required maxlength="180"></label><label>Длительность, минут<input v-model="journey.duration" type="number" min="10" max="1440" required></label><label class="wide">Описание<textarea v-model="journey.description" maxlength="2000"></textarea></label><div class="wide"><p class="muted">Выберите места в порядке посещения.</p><label v-for="p in data.places" :key="p.id" class="check-label my-2"><input v-model="journey.stops" :value="p.id" type="checkbox">{{p.name}} <small v-if="journey.stops.includes(p.id)">Точка {{journey.stops.indexOf(p.id)+1}}</small></label></div><div class="wide"><button class="primary" :disabled="journey.processing||journey.stops.length<2">Опубликовать маршрут</button></div></form></section>
<section v-if="section==='Заявки инвесторов'" class="workspace-section"><h2>Заявки в «одно окно»</h2><article v-for="r in requests" :key="r.id" class="queue-row"><h3>{{r.project}}</h3><p>{{r.description}}</p><p>Контакт: {{r.contact}}</p><form class="workspace-form" @submit.prevent="updateRequest($event,r.id)"><label>Статус<select name="status" :value="r.status"><option v-for="s in ['new','in_progress','approved','rejected']" :key="s" :value="s">{{statuses[s]}}</option></select></label><label>Ответ заявителю<input name="response" :value="r.response" maxlength="2000"></label><div><button class="primary">Сохранить</button></div></form></article><p v-if="!requests.length" class="muted">Заявок пока нет.</p></section>
<footer class="page-footer"><span>Учебный прототип. Данные демонстрационные.</span><Link href="/security" class="text-link"><ShieldCheck :size="15"/>Защита аккаунта</Link></footer>
</main>
</template>

